-- قاعدة البيانات مغلقة تماماً أمام المتصفح: لا وصول مباشر للجداول، كل شيء عبر الخادم (Edge Function)
do $$ declare t text; begin
  for t in select tablename from pg_tables where schemaname = 'mobily' and tablename like 'mc\_%' loop
    execute format('alter table mobily.%I enable row level security', t);
    execute format('revoke all on mobily.%I from anon, authenticated', t);
  end loop;
end $$;
